WindowView = class("WindowView", View)

function WindowView:ctor(entity)
    self.uiWindow = nil;
    WindowView.super.ctor(self, entity);
    --Debug.LogWarning("==>>WindowView:ctor->"..tostring(self).." | "..tostring(entity));
end

-- 各个子View从Page获取所需的部件，存入self。
function WindowView:Load(callback)
    --Debug.LogWarning("----->WindowView:Load");
    --if LuaRefreshScript.pageArr[self.__cname] then --加载过的不加载,重启lua用
    --    return
    --end
    local uiWindow = nil;
    uiSystem:CreateWindowX(self.name, function(window, exist)
        --Debug.LogWarning("WindowView:Load===>>>>"..tostring(exist));
        uiWindow = window;
        if exist == false then
            if uiWindow == nil then
                GameDebugger.sPushLog("Create window failed!-"..self.name);
            else
                self.uiWindow = uiSystem:GetWindow(self.name);
                self.gameObject = self.uiWindow.gameObject;
                self.transform = self.gameObject.transform;
                --LuaRefreshScript.pageArr[self.__cname] = self.uiWindow --存储加载好的对象,重启lua用
                GameDebugger.sPushLog("[Lua]View完成加载:"..self.name.."-"..tostring(self.uiWindow));
            end
            WindowView.super.Load(self, callback);
        end
    end);
end

function WindowView:OnViewLoad()
    --Debug.LogWarning("----->WindowView:OnViewLoad");
    WindowView.super.OnViewLoad(self);
end